import{_ as s,I as r,c as i,o,ag as a,J as n}from"./chunks/framework.Vyheyqg9.js";const g=JSON.parse('{"title":"Caching, delivery and repeat visits","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/performance/caching.md","filePath":"frontend/performance/caching.md"}'),c={name:"frontend/performance/caching.md"};function l(d,e,h,p,u,f){const t=r("MermaidDiagram");return o(),i("div",null,[e[0]||(e[0]=a('<h1 id="caching-delivery-and-repeat-visits" tabindex="-1">Caching, delivery and repeat visits <a class="header-anchor" href="#caching-delivery-and-repeat-visits" aria-label="Permalink to “Caching, delivery and repeat visits”">​</a></h1><p><strong>Prerequisite:</strong> HTTP responses, browser origins and resource lifetime. Caching trades freshness and storage for reuse. Begin with a resource policy, not “cache everything.” A public course thumbnail, a logged-in management response and an application HTML entry need different treatment.</p><h2 id="name-the-cache-and-its-authority" tabindex="-1"><span class="hub-section-number">1 </span>Name the cache and its authority <a class="header-anchor" href="#name-the-cache-and-its-authority" aria-label="Permalink to “1 Name the cache and its authority”">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>What it can reuse</th><th>Ownership question</th></tr></thead><tbody><tr><td>HTTP browser cache</td><td>Responses under HTTP freshness/validation rules</td><td>When must this user revalidate?</td></tr><tr><td>CDN/shared HTTP cache</td><td>Eligible responses across users</td><td>Could a cache key or policy expose private content?</td></tr><tr><td>Service-worker Cache Storage</td><td>Request/response entries managed by application code</td><td>Who versions, expires and deletes them?</td></tr><tr><td>Application/query cache</td><td>Parsed domain results</td><td>Which query/user/version owns a value and its invalidation?</td></tr></tbody></table><p>A request intercepted by a controlling service worker can be answered from Cache Storage or forwarded using fetch, which may then use HTTP caching and a CDN. This is not an automatic mandatory cache ladder. Without an appropriate fetch handler, cached entries are not automatically served. Cache Storage does not automatically enforce HTTP Cache-Control freshness like an HTTP cache. <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching" target="_blank" rel="noreferrer">HTTP caching</a>, <a href="https://developer.mozilla.org/en-US/docs/Web/API/Cache" target="_blank" rel="noreferrer">Cache interface</a>.</p><h2 id="freshness-versus-validation" tabindex="-1"><span class="hub-section-number">2 </span>Freshness versus validation <a class="header-anchor" href="#freshness-versus-validation" aria-label="Permalink to “2 Freshness versus validation”">​</a></h2>',6)),n(t,{"encoded-source":"sequenceDiagram%0A%20%20participant%20B%20as%20Browser%20HTTP%20cache%0A%20%20participant%20S%20as%20Origin%20or%20CDN%0A%20%20B-%3E%3ES%3A%20First%20GET%0A%20%20S--%3E%3EB%3A%20200%2C%20max-age%3D60%2C%20ETag%20v1%0A%20%20Note%20over%20B%3A%20Store%20response%20and%20reuse%20while%20fresh%0A%20%20B-%3E%3ES%3A%20Stale%20request%2C%20If-None-Match%20v1%0A%20%20alt%20Representation%20unchanged%0A%20%20%20%20S--%3E%3EB%3A%20304%20with%20updated%20cache%20metadata%0A%20%20%20%20Note%20over%20B%3A%20Reuse%20stored%20body%0A%20%20else%20Representation%20changed%0A%20%20%20%20S--%3E%3EB%3A%20200%20with%20new%20body%20and%20ETag%0A%20%20end"}),e[1]||(e[1]=a(`<p><code>no-store</code> instructs caches not to store this response; it is not retroactive deletion of every prior copy. <code>no-cache</code> allows storage but requires successful validation before reuse. <code>max-age</code> defines freshness; <code>must-revalidate</code> constrains stale reuse. ETags can be weak or strong; Last-Modified can be another validator. A 304 carries validation metadata, not the full representation body. <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">Cache-Control reference</a>.</p><p>Illustrative policies for an owned deployment:</p><div class="language-http"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Content-hashed public assets; never overwrite a URL with different bytes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public, max-age=31536000, immutable</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Public HTML that should validate before reuse</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> no-cache</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Sensitive response chosen not to be stored</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> no-store</span></span></code></pre></div><p>Choose the actual policy with security/freshness needs. <code>private</code> prevents shared-cache storage but is not encryption or authorization. Personalized output must not enter public caches accidentally. Account/tenant scope and logout behavior also matter in an application cache and service-worker code, not just headers. Service-worker code should explicitly bypass sensitive APIs when offline caching is unnecessary.</p><h2 id="cdn-and-compression" tabindex="-1"><span class="hub-section-number">3 </span>CDN and compression <a class="header-anchor" href="#cdn-and-compression" aria-label="Permalink to “3 CDN and compression”">​</a></h2><p>A nearby edge and warm shared cache can reduce origin round trips; a cold miss, wrong cache key or origin bottleneck still matters. Inspect hit/miss headers and actual geographic/user conditions. Serve negotiated compression for text resources, and compare transferred versus decoded bytes. Already compressed image/font formats do not automatically benefit from another compression layer. Cache keys and variation must preserve the correct content representation.</p><p>The old S3/CloudFront console screenshots teach a provider-specific workflow with dated public-bucket settings. They are not needed to learn the delivery model. Keep infrastructure setup in <a href="./../../node-js/full-stack-deployment.html">full-stack deployment</a>, and review current provider documentation before configuring a real environment. Do not copy a public bucket policy to solve a frontend timing problem.</p><h2 id="service-workers-are-an-optional-offline-capability" tabindex="-1"><span class="hub-section-number">4 </span>Service workers are an optional offline capability <a class="header-anchor" href="#service-workers-are-an-optional-offline-capability" aria-label="Permalink to “4 Service workers are an optional offline capability”">​</a></h2><p>A service worker requires a secure context (localhost is a development exception), registration and appropriate scope. First navigation usually precedes control. A successful registration does not mean every open page is immediately controlled or cached. Separate registration, installation, waiting, activation and fetch handling. <a href="https://developer.mozilla.org/en-US/docs/Web/API/Service_Worker_API" target="_blank" rel="noreferrer">Service Worker API</a>.</p>`,9)),n(t,{"encoded-source":"flowchart%20LR%0A%20%20R%5BRegister%5D%20--%3E%20I%5BInstall%20new%20version%5D%0A%20%20I%20--%3E%20W%5BWait%20while%20older%20version%20controls%20clients%5D%0A%20%20W%20--%3E%20A%5BActivate%5D%0A%20%20A%20--%3E%20F%5BHandle%20fetch%20and%20other%20events%5D%0A%20%20I%20--%3E%7CInstall%20failure%7C%20X%5BDiscard%20new%20version%5D"}),e[2]||(e[2]=a('<p>The waiting step can be skipped when there are no existing controlled clients. Forced activation/claiming needs deliberate compatibility decisions. Precache essential versioned files with <code>install</code>/<code>event.waitUntil</code>; keep activation short and delete only caches owned by this application. Deleting every origin cache can break another application. Cache writes after responding still need lifetime/error handling; cloning a Response permits separate consumers of its body.</p><table tabindex="0"><thead><tr><th>Strategy</th><th>Useful when</th><th>Failure mode</th></tr></thead><tbody><tr><td>Cache first</td><td>Versioned public assets</td><td>Old content persists without version cleanup</td></tr><tr><td>Network first</td><td>Fresh public content with acceptable offline fallback</td><td>Slow network delays fallback; use an explicit policy/deadline</td></tr><tr><td>Stale while revalidate</td><td>Stale public content is temporarily acceptable</td><td>Background failure or unbounded storage can go unnoticed</td></tr><tr><td>Network only / bypass</td><td>Sensitive or mutation endpoints</td><td>Requires honest offline/unavailable UI</td></tr></tbody></table><p>Cache only can fail offline if an expected entry was evicted; persistence is never a reason to omit recovery. Do not cache arbitrary URLs or opaque/private responses indiscriminately. Read storage usage through <code>navigator.storage.estimate()</code> where supported; <code>persist()</code> is a request, not an unconditional guarantee. Push/background sync are optional capabilities with separate support and permission concerns, not prerequisites for frontend performance.</p><h2 id="deployment-is-a-cache-correctness-test" tabindex="-1"><span class="hub-section-number">5 </span>Deployment is a cache correctness test <a class="header-anchor" href="#deployment-is-a-cache-correctness-test" aria-label="Permalink to “5 Deployment is a cache correctness test”">​</a></h2><p>Retain old content-hashed assets for a defined compatibility window, revalidate entry HTML, and test an old open tab after a new release. A stale HTML entry plus deleted chunks causes feature-open failures. Test offline behavior and update/rollback separately from warm navigation timing. Framework caches are additional layers: use the explicitly selected <a href="./../next.html">Next cache model</a>, not assumptions copied from another version.</p><p>Core practice: plan appropriate delivery/cache improvements in <a href="./../../practice/frontend/performance/">Hometasks 2–3</a>. Implementing an offline service worker is an optional extension with its own lifecycle, eviction and privacy acceptance cases.</p>',6))])}const b=s(c,[["render",l]]);export{g as __pageData,b as default};
